import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Techniques & Specialization","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/characters/techniques-and-specialization.md","filePath":"game-design/characters/techniques-and-specialization.md"}'),r={name:"game-design/characters/techniques-and-specialization.md"};function s(o,e,l,c,d,h){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="techniques-specialization" tabindex="-1">Techniques &amp; Specialization <a class="header-anchor" href="#techniques-specialization" aria-label="Permalink to &quot;Techniques &amp; Specialization&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; open questions remain Unresolved. Referenced Accepted decisions retain their existing scope. <strong>Implementation/availability:</strong> no changes to gameplay or runtime configuration; this redesign is not established as live. <strong>Verification:</strong> documentation review, not a playtest; current availability is not established here. <strong>Reviewed:</strong> 2026-10-09 for public projection; design status and mechanics preserved from the canonical specification.</p><p><a href="/Syrolands-Public/guide/characters/techniques.html">Player-facing overview</a> · <a href="/Syrolands-Public/game-design/characters/progression.html">Character progression</a></p><h2 id="skill-learned-knowledge-and-identity" tabindex="-1">Skill, learned knowledge and identity <a class="header-anchor" href="#skill-learned-knowledge-and-identity" aria-label="Permalink to &quot;Skill, learned knowledge and identity&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Meaning</th><th>Examples</th></tr></thead><tbody><tr><td>Skill</td><td>Broad underlying capability</td><td>Carpentry, Blacksmithing, Tinkering</td></tr><tr><td>Technique / School</td><td>Concrete learned knowledge within or across skills</td><td>Bowmaking, Advanced Tillering, Bladesmithing, Armorsmithing, Luthiery, Distillation, Toxicology</td></tr><tr><td>Profession Path</td><td>Specialized practical identity from skills, techniques, experience and reputation</td><td>Master Bowyer</td></tr><tr><td>Endgame Identity</td><td>What a particular character becomes known for in the world</td><td>A bowyer famous for highly durable war bows</td></tr></tbody></table><p>This centralizes Batch 01&#39;s hierarchy for characters generally. A capable carpenter may still not know Bowmaking; a technically skilled blacksmith may not know a rare bladesmithing school. This separation is intentional.</p><p><strong>Skill determines capability; knowledge determines possibility/information; player mastery determines performance.</strong> The <a href="/Syrolands-Public/game-design/characters/progression.html#character-skill-knowledge-and-player-mastery">progression framework</a> owns the three-axis principle and examples. The <a href="/Syrolands-Public/game-design/professions/profession-system.html#character-journals-and-discovery">Profession System</a> owns craft journals, observed discoveries and knowledge-sharing constraints.</p><h2 id="learning-techniques-and-schools" tabindex="-1">Learning techniques and schools <a class="header-anchor" href="#learning-techniques-and-schools" aria-label="Permalink to &quot;Learning techniques and schools&quot;">​</a></h2><p>Possible sources include NPC masters, academies, guilds, manuscripts, exploration, quests/challenges, competitions, reputation, player teaching and reverse engineering where appropriate. A possible hierarchy is <strong>Fundamentals → Advanced Techniques → Master Techniques</strong>, not an approved perk tree or automatic skill unlock ladder.</p><p>Techniques are concrete procedures and understanding, not abstract bonus nodes. Do not make all techniques mutually exclusive by default. Specialization should emerge primarily through skill-cap investment, time, acquiring knowledge, practice and reputation rather than arbitrary class locks.</p><p>Having a technique and being able to execute it well are distinct. High skill alone does not grant every technique, and copied instructions do not remove character capability requirements. <a href="/Syrolands-Public/game-design/professions/carpentry.html#bowmaking-and-fletching">Bowmaking/Fletching</a> remains within Carpentry/Archery, pending reconciliation of the legacy skill roster; this page removes no skill.</p><h2 id="persistence-and-information-boundary" tabindex="-1">Persistence and information boundary <a class="header-anchor" href="#persistence-and-information-boundary" aria-label="Permalink to &quot;Persistence and information boundary&quot;">​</a></h2><p>Persistent character knowledge is a design direction, not a selected schema. Teaching intent is a client request; actual learned knowledge and execution eligibility are server decisions; synchronized knowledge is limited to approved disclosure; the journal/UI is presentation. Follow authority and persistence constraints in later technical work.</p><p>Public capability descriptions can explain progression without revealing every hidden school, recipe or interaction. Technique names in this batch are examples, not a complete catalogue or promised acquisition route.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Exact teacher/player-teaching rules; prerequisites and recognition of fundamentals; whether any specific schools conflict; costs and reputation requirements; knowledge persistence, ownership/custody and transfer; respec/forgetting; discovery versus taught knowledge; how capability UI reveals possibilities without spoiling secrets. No universal exclusivity, technique slot cap or knowledge loss rule is selected.</p>',16)])])}const g=a(r,[["render",s]]);export{u as __pageData,g as default};
